"""Opening-only Boss curriculum; skipped fights never become learner samples.

Route resources are kept exactly as generated by native skip_battles and the
public overworld rules. This is a synthetic distribution, not natural arrivals.
The immutable seed/action journal reconstructs GameContext callbacks; only the
live BattleContext is cloned. There are no monster-phase or combat-action rules.
"""
from __future__ import annotations

from functools import lru_cache
import hashlib
import json
from pathlib import Path

import numpy as np

from . import action_space as A
from .combat_value import combat_terminal_outcome
from .game_env import SimGameEnv, _CombatBranchGameEnv
import slaythespire as sts

CONTRACT = 'boss-opening-skip-route-v1'
BOSSES = ('CHAMP', 'AUTOMATON', 'COLLECTOR')


def _digest(value):
    return hashlib.sha256(json.dumps(value, sort_keys=True, separators=(',', ':')).encode()).hexdigest()


def opening_digest(backend):
    return _digest({'battle': backend.bc.to_dict(), 'global': backend.obs_canonical()['global']})


def _enter_target(backend):
    return (backend.phase() == 'map' and int(backend.gc.act) == 2
            and int(backend.gc.cur_map_node_y) >= 14)


def _check_opening(backend):
    if (backend.bc is None or backend.bc.is_battle_over or int(backend.gc.act) != 2
            or str(backend.gc.cur_room).split('.')[-1] != 'BOSS' or backend.gc.skip_battles):
        raise ValueError('route did not finish at a live Act 2 Boss opening')
    boss = str(backend.gc.encounter).split('.')[-1]
    if boss not in BOSSES:
        raise ValueError(f'unsupported Act 2 boss: {boss}')
    return boss


def generate_opening(seed: int, *, ascension: int = 0):
    """Bounded public-rule route; return a portable journal and its live opening.

    Unsupported rule screens fail explicitly instead of choosing a hidden or
    model-dependent fallback. Dataset builders must report rejected seeds.
    """
    from env.search.overworld_rules import OVERWORLD_RULE_VERSION, rank_overworld

    _require_native_route()

    backend = SimGameEnv(ascension=ascension, global_map_view=True)
    backend.reset(seed=seed)
    journal = []
    for _ in range(5000):
        if backend.is_over:
            raise ValueError('route terminated before the target Boss')
        enter = _enter_target(backend)
        backend.gc.skip_battles = not enter
        phase = backend.phase()
        if phase == 'combat':
            raise ValueError('unexpected live combat during route generation')
        legal = backend.legal_semantic_actions()
        ranked = rank_overworld(backend.obs_canonical(), A.legal_ids(legal, None, phase),
                                rmap=backend.rmap, current_y=backend.gc.cur_map_node_y)
        if not ranked:
            raise ValueError(f'unsupported public-rule route screen: {phase}')
        action, pending = A.resolve(ranked[0]['action'], legal, None, phase)
        if action is None or pending is not None:
            raise ValueError('route action unexpectedly requires a combat prefix')
        journal.append(action)
        backend.step(action)
        if enter:
            boss = _check_opening(backend)
            return dict(source_seed=int(seed), ascension=int(ascension), boss=boss,
                        rule_version=OVERWORLD_RULE_VERSION, actions=journal,
                        opening_sha256=opening_digest(backend)), backend
    raise RuntimeError('Boss route exceeded 5000 actions')


def replay_opening(entry):
    _require_native_route()
    backend = SimGameEnv(ascension=int(entry['ascension']), global_map_view=True)
    backend.reset(seed=int(entry['source_seed']))
    actions = entry['actions']
    if not 0 < len(actions) <= 5000:
        raise ValueError('invalid Boss opening route length')
    for index, action in enumerate(actions):
        if backend.is_over or backend.bc is not None:
            raise ValueError('Boss opening journal contains post-opening actions')
        enter = _enter_target(backend)
        if enter != (index == len(actions) - 1):
            raise ValueError('Boss entrance must be the final route action')
        backend.gc.skip_battles = not enter
        semantic = tuple(action)
        if semantic not in backend.legal_semantic_actions():
            raise ValueError('Boss route journal contains an illegal action')
        backend.step(semantic)
    if _check_opening(backend) != entry['boss'] or opening_digest(backend) != entry['opening_sha256']:
        raise ValueError('Boss opening replay diverged')
    return backend


def _require_native_route():
    if getattr(sts, 'boss_opening_route_version', lambda: 0)() != 1:
        raise RuntimeError('Boss openings require the native skipped-fight charge fix')


class BossOpeningPool:
    """Validated dataset and bounded, read-only native opening cache."""
    def __init__(self, path):
        self.path = Path(path).resolve()
        raw = self.path.read_bytes()
        self.sha256 = hashlib.sha256(raw).hexdigest()
        data = json.loads(raw)
        if data.get('contract') != CONTRACT:
            raise ValueError('unsupported Boss dataset contract')
        self.entries = tuple(data['entries'])
        seeds = [int(e['source_seed']) for e in self.entries]
        if not seeds or len(set(seeds)) != len(seeds):
            raise ValueError('Boss opening source seeds must be nonempty and unique')
        self.groups = {boss: tuple(i for i, e in enumerate(self.entries) if e['boss'] == boss)
                       for boss in BOSSES}
        if sum(map(len, self.groups.values())) != len(self.entries):
            raise ValueError('unknown Boss in dataset')
        self.opening = lru_cache(maxsize=min(512, len(self.entries)))(self._opening)

    def _opening(self, index):
        return replay_opening(self.entries[index])

    def factory(self, *, boss=None, fixed_index=None, ascension=0):
        if any(int(e['ascension']) != ascension for e in self.entries):
            raise ValueError('Boss dataset ascension mismatch')
        if boss is not None and not self.groups.get(boss):
            raise ValueError(f'empty Boss group: {boss}')
        if fixed_index is not None and not 0 <= fixed_index < len(self.entries):
            raise ValueError('Boss opening index out of range')
        return lambda: BossOpeningGameEnv(self, boss=boss, fixed_index=fixed_index)


class BossOpeningGameEnv(_CombatBranchGameEnv):
    """One complete fight. Run metadata stays read-only, even after victory."""
    def __init__(self, pool, *, boss=None, fixed_index=None):
        self._pool, self._boss, self._fixed_index = pool, boss, fixed_index
        self.bc = self.gc = None

    def reset(self, *, seed=None):
        pool, boss, fixed_index = self._pool, self._boss, self._fixed_index
        indices = pool.groups[boss] if boss else tuple(range(len(pool.entries)))
        index = (fixed_index if fixed_index is not None else
                 indices[int(np.random.default_rng(seed).integers(len(indices)))])
        _CombatBranchGameEnv.__init__(self, pool.opening(index))
        self._pool, self._boss, self._fixed_index = pool, boss, fixed_index
        self.opening_index = index
        return self._canonical(), self._info()

    def training_identity(self):
        return {'contract': CONTRACT, 'dataset_sha256': self._pool.sha256,
                'boss': self._boss, 'fixed_index': self._fixed_index}

    def run_stats(self):
        stats = super().run_stats()
        outcome = combat_terminal_outcome(self.bc) if self.is_over else 'live'
        entry = self._pool.entries[self.opening_index]
        stats.update(episode_scope='boss-opening', boss=entry['boss'],
                     source_seed=entry['source_seed'], hp=int(self.bc.to_dict()['player']['hp']),
                     outcome={'win':'PLAYER_VICTORY', 'loss':'PLAYER_LOSS'}.get(outcome, 'UNDECIDED'),
                     combat_outcome=outcome)
        return stats


def boss_episode_outcome(env, info, terminated, truncated):
    """Explicit fight outcome; escaping/truncation is never a win or a loss."""
    stats = env.unwrapped.thick.run_stats()
    result = ('other_truncation' if truncated else
              {'win':'win', 'loss':'death'}.get(stats['combat_outcome'], 'censored'))
    return dict(result=result, floor=int(stats['floor']), act=int(stats['act']),
                outcome=stats['outcome'], boss=stats['boss'], source_seed=stats['source_seed'],
                remaining_hp=stats['hp'], episode_scope='boss-opening')
